/**
 * Light pillar shader.
 *
 * ## The mathematical idea
 *
 * A vertical column is a distance to an axis. Two profiles are laid over
 * it: a narrow gaussian for the core, a wide exponential for the halo —
 * real light has a sharp centre and a trail which never quite ends, and a
 * single curve cannot give both.
 *
 * The breathing is the width oscillating, on two periods that are not
 * multiples so as not to beat like a metronome. The streaks are a 1D noise
 * of the height, climbing: three sines of frequencies that are not
 * multiples, so the light seems to flow inside the column rather than
 * blink.
 *
 * The light is laid over the background by a bounded mix towards its hues,
 * never by darkening: the column stays legible on a light background.
 *
 * ## Uniforms
 *
 * - `uTime` — time in seconds, supplied by the engine.
 * - `uResolution` — canvas size in pixels, supplied by the engine.
 * - `uColorA` — the background.
 * - `uColorB` — the halo.
 * - `uColorC` — the core.
 * - `uX` — horizontal position of the axis, as a fraction of the frame.
 * - `uWidth` — width of the core, as a fraction of the height.
 * - `uBreath` — speed of the breathing.
 * - `uGlow` — extent of the halo.
 * - `uDetail` — number of harmonics in the streaks, and so their cost.
 */
export const LIGHT_PILLAR_FRAGMENT = /* glsl */ `
precision highp float;

varying vec2 vUv;

uniform float uTime;
uniform vec2 uResolution;
uniform vec3 uColorA;
uniform vec3 uColorB;
uniform vec3 uColorC;
uniform float uX;
uniform float uWidth;
uniform float uBreath;
uniform float uGlow;
uniform float uDetail;

void main() {
  float aspect = uResolution.x / max(uResolution.y, 1.0);
  vec2 p = vec2(vUv.x * aspect, vUv.y);
  float axis = uX * aspect;
  float t = uTime;
  int harmonics = int(clamp(uDetail, 1.0, 3.0));

  // The breathing: two periods that are not multiples, so the column never
  // beats twice the same way.
  float breath = 0.5
    + 0.3 * sin(t * uBreath * 1.3)
    + 0.2 * sin(t * uBreath * 0.47 + 1.7);
  float width = max(uWidth, 0.01) * (0.8 + 0.4 * breath);

  // The streaks: a 1D noise of the climbing height, in bounded harmonics.
  float streak = 0.5 + 0.5 * sin(vUv.y * 9.0 - t * 0.8);
  if (harmonics >= 2) {
    streak = streak * 0.6 + (0.5 + 0.5 * sin(vUv.y * 23.0 + t * 1.3)) * 0.4;
  }
  if (harmonics >= 3) {
    streak = streak * 0.75 + (0.5 + 0.5 * sin(vUv.y * 51.0 - t * 2.1)) * 0.25;
  }

  // The core, gaussian and sharp; the halo, exponential and endless.
  float d = abs(p.x - axis);
  float core = exp(-(d * d) / (width * width * 0.25));
  float halo = exp(-d / (width * 4.0)) * uGlow;

  // The ends: the column fades out towards the edges, a little faster at the
  // top, like a jet scattering as it rises.
  float height = smoothstep(0.0, 0.18, vUv.y) * smoothstep(1.0, 0.7, vUv.y);

  // The foot: the light touching the ground spreads into a pool.
  float foot = exp(-(d * d) * 6.0 - vUv.y * vUv.y * 30.0) * 0.5;

  // The streaks mark the core; on the halo they only just surface, otherwise
  // they bar the whole frame with horizontal bands.
  float veil = clamp((halo * (0.88 + 0.12 * streak) + foot) * height, 0.0, 1.0);
  vec3 colour = mix(uColorA, uColorB, veil);
  colour = mix(colour, uColorC, clamp(core * height * (0.6 + 0.4 * streak), 0.0, 1.0));
  colour += uColorC * core * height * 0.25 * breath;

  gl_FragColor = vec4(clamp(colour, 0.0, 1.0), 1.0);
}
`

sources.component.tsx:
/**
 * Light pillar: a vertical column that breathes: a sharp gaussian core, an endless exponential halo, streaks that climb.
 *
 * ## The principle
 *
 * A column is a distance to an axis: a narrow gaussian for the core, a
 * wide exponential for the halo, because a single curve cannot give both
 * the sharp centre and the endless trail of light. The width breathes on
 * two periods that are not multiples, and a 1D noise of the height makes
 * the light flow inside the column.
 *
 * ## What this component delegates
 *
 * It carries only what sets it apart: its shader, its settings and its fallback.
 * Reading the tokens, converting them to floats and re-reading them when the
 * theme changes all come from the engine — copying them here would leave as
 * many versions to maintain as there are backgrounds.
 *
 * The fallback is not a precaution: it is shown while the backend loads, when
 * WebGL is missing, when the arbiter refuses the surface — it grants only one
 * per backend — and under reduced motion.
 *
 * @module
 */

import {
  mergePresentation,
  useOnReady,
  useTokenShader,
  type Customisable,
  type ReadyCallback,
  type ShaderColour,
} from '@odoro-cli/engine'
import { type ReactElement } from 'react'

import { LIGHT_PILLAR_FRAGMENT } from './light-pillar.shader.js'

/** What the escape hatch receives. */
export interface LightPillarControls {
  /** Colours actually handed to the shader. */
  readonly colours: readonly ShaderColour[]
  /** Reason for the refusal, if there is one. */
  readonly refused: string | undefined
}

/** Properties specific to this component. */
export interface LightPillarOwnProps {
  /** Horizontal position of the axis, as a fraction of the frame. @defaultValue 0.5 */
  x?: number
  /** Width of the core, as a fraction of the height. @defaultValue 0.12 */
  width?: number
  /** Speed of the breathing. @defaultValue 0.6 */
  breath?: number
  /** Extent of the halo. @defaultValue 0.8 */
  glow?: number
  /** Tokens whose colours are read. */
  colors?: readonly string[]
  /** Fallback classes. */
  fallback?: string
  /** Escape hatch. */
  onReady?: ReadyCallback<LightPillarControls>
}

/** Every property. */
export type LightPillarProps = Customisable<LightPillarOwnProps>

/** Tokens used by default: the background, the halo, the core. */
const DEFAULT_TOKENS = [
  '--o-theme-bg',
  '--o-palette-sky-400',
  '--o-palette-amber-200',
] as const

/** Default fallback: a frozen gradient, in the same tones. */
const DEFAULT_FALLBACK =
  'o-bg-gradient-to-r o-from-zinc-50 dark:o-from-zinc-950 o-via-sky-200 dark:o-via-sky-900 o-to-zinc-50 dark:o-to-zinc-950'

/**
 * Detail outside low quality.
 *
 * The column costs nothing; it is the harmonics of the streaks which
 * weigh, so those are what gets capped.
 */
const DETAIL = 3

/** Detail at low quality. */
const LOW_DETAIL = 1

/**
 * Light pillar.
 *
 * @example
 * <div className="o-relative o-min-h-screen">
 *   <LightPillar className="o-absolute o-inset-0" />
 *   <main className="o-relative">…</main>
 * </div>
 */
export function LightPillar({
  x = 0.5,
  width = 0.12,
  breath = 0.6,
  glow = 0.8,
  colors = DEFAULT_TOKENS,
  fallback = DEFAULT_FALLBACK,
  onReady,
  ...rest
}: LightPillarProps): ReactElement {
  const { ref, setHost, ready, refused, colours } = useTokenShader<HTMLDivElement>({
    fragment: LIGHT_PILLAR_FRAGMENT,
    colors,
    uniforms: {
      uX: x,
      uWidth: width,
      uBreath: breath,
      uGlow: glow,
      uDetail: DETAIL,
    },
    name: 'light-pillar',
    degrade: (quality) => ({
      uDetail: quality === 'low' ? LOW_DETAIL : DETAIL,
    }),
  })

  useOnReady(onReady, ready ? { colours, refused } : null, ref.current)

  const { className, style } = mergePresentation(
    { className: 'o-relative o-overflow-hidden' },
    rest,
  )

  return (
    <div
      {...rest}
      ref={(element) => {
        setHost(element)
        ref.current = element
      }}
      className={className}
      style={style}
      aria-hidden
    >
      {ready && refused === undefined ? null : (
        <div className={`o-absolute o-inset-0 ${fallback}`} />
      )}
    </div>
  )
}
